-- SQL Dump Varietas Terdaftar Kementan PROSEED
CREATE TABLE IF NOT EXISTS `registered_varieties` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `external_id` int(11) DEFAULT NULL,
  `nama_varietas` varchar(255) NOT NULL,
  `komoditas` varchar(255) DEFAULT NULL,
  `kategori` varchar(100) DEFAULT NULL,
  `produsen` varchar(255) DEFAULT NULL,
  `no_sk` varchar(255) DEFAULT NULL,
  `tahun_daftar` varchar(50) DEFAULT NULL,
  `no_reg` varchar(255) DEFAULT NULL,
  `upload_deskripsi` text DEFAULT NULL,
  `upload_produk` text DEFAULT NULL,
  `wil_adaptasi` text DEFAULT NULL,
  `tahan_opt` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_var_nama` (`nama_varietas`),
  KEY `idx_var_komoditas` (`komoditas`),
  KEY `idx_var_kategori` (`kategori`),
  KEY `idx_var_tahun` (`tahun_daftar`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

